using System.Collections.Frozen;
using System.Reflection;

namespace Plus.HabboHotel.Items;

/// <summary>
/// The directions each floor furni has, as the client knows them: logic.model.directions in its .hab asset, the list AIR keeps
/// as furniture_allowed_directions (AIR WIN63-202610151745-318700621, room/object/logic/furniture/class_1777.as:181-196).
/// The table is FurnitureDirections.tsv, generated by scripts/build-furniture-directions.py. Values are in wired units
/// (degrees / 45), sorted. A furni missing from the table keeps the old rule: even directions, odd ones only with extra_rot.
/// </summary>
public static class FurnitureDirections
{
    private const string Resource = "Plus.Items.FurnitureDirections.tsv";
    private static readonly Lazy<FrozenDictionary<string, int[]>> Table = new(Load);

    /// <summary>The directions of a classname; colour variants ("name*3") share their base asset. Empty when unknown.</summary>
    public static IReadOnlyList<int> For(string? itemName)
    {
        if (string.IsNullOrEmpty(itemName)) {
            return [];
        }

        var star = itemName.IndexOf('*');

        return Table.Value.TryGetValue(star < 0 ? itemName : itemName[..star], out var directions) ? directions : [];
    }

    /// <summary>Whether the furni may face a rotation: one of its directions, or an even one (odd with extra_rot) as before.</summary>
    public static bool Allows(ItemDefinition definition, int rotation) =>
        rotation is >= 0 and <= 7 && (definition.Directions.Contains(rotation) || definition.ExtraRot || rotation % 2 == 0);

    /// <summary>
    /// The rotation a furni takes when it heads somewhere, or null when it cannot face that way and keeps its rotation.
    /// A heading the furni lacks falls back to the opposite direction on the same axis. Observed on AIR
    /// WIN63-202610151745-318700621: a projectile wf_antenna2 (directions 0, 2) flying west (6) landed with rotation 2, and a
    /// wf_colortile (direction 0 only) kept rotation 0.
    /// </summary>
    public static int? Heading(ItemDefinition definition, int heading)
    {
        heading = (heading % 8 + 8) % 8;
        var directions = definition.Directions;

        if (directions.Count == 0) {
            return Allows(definition, heading) ? heading : null;
        }

        if (directions.Contains(heading)) {
            return heading;
        }

        var opposite = (heading + 4) % 8;

        return directions.Contains(opposite) ? opposite : null;
    }

    /// <summary>
    /// A quarter turn clockwise or counterclockwise that skips directions the furni lacks, so a furni with one direction
    /// stays put. Observed on AIR WIN63-202610131318-860371703: Move/Rotate clockwise on a wf_colortile sends no update.
    /// </summary>
    public static int Turn(ItemDefinition definition, int rotation, bool clockwise)
    {
        var step = clockwise ? 2 : 6;
        var directions = definition.Directions;

        if (directions.Count == 0) {
            return (rotation + step) % 8;
        }

        for (var turned = (rotation + step) % 8; turned != rotation; turned = (turned + step) % 8) {
            if (directions.Contains(turned)) {
                return turned;
            }
        }

        return rotation;
    }

    internal static FrozenDictionary<string, int[]> Parse(TextReader reader)
    {
        var table = new Dictionary<string, int[]>(StringComparer.Ordinal);

        while (reader.ReadLine() is { } line) {
            if (line.Length == 0 || line[0] == '#') {
                continue;
            }

            var tab = line.IndexOf('\t');

            if (tab <= 0) {
                continue;
            }

            var directions = line[(tab + 1)..].Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Select(value => int.TryParse(value, out var direction) ? direction : -1)
                .Where(direction => direction is >= 0 and <= 7)
                .Distinct()
                .Order()
                .ToArray();

            if (directions.Length > 0) {
                table[line[..tab]] = directions;
            }
        }

        return table.ToFrozenDictionary(StringComparer.Ordinal);
    }

    private static FrozenDictionary<string, int[]> Load()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(Resource)
            ?? throw new InvalidOperationException($"Missing embedded resource {Resource}.");
        using var reader = new StreamReader(stream);

        return Parse(reader);
    }
}
